import type { StorybookConfig } from '@storybook/react-vite';

const config: StorybookConfig = {
  stories: ['../src/**/*.stories.@(ts|tsx)'],
  framework: '@storybook/react-vite',
};
export default config;

import type { Preview } from '@storybook/react-vite';
import '../src/ui/theme.css';

// Light/dark from the toolbar, applied the same way the app does: Primer's
// data-color-mode attribute on <html>.
const preview: Preview = {
  globalTypes: {
    colorMode: {
      description: 'Light or dark',
      toolbar: { title: 'Color mode', icon: 'mirror', items: ['light', 'dark'], dynamicTitle: true },
    },
  },
  initialGlobals: { colorMode: 'light' },
  decorators: [
    (Story, context) => {
      const html = document.documentElement;
      html.setAttribute('data-color-mode', context.globals.colorMode);
      html.setAttribute('data-light-theme', 'light');
      html.setAttribute('data-dark-theme', 'dark');
      return <Story />;
    },
  ],
  parameters: { layout: 'padded' },
};
export default preview;

// Builds the "pridm reviewing its own build" fixture for Storybook: every file
// changed between pridm's first commit and HEAD, with its contents.
//
//   bun scripts/fixture-self.ts

import { writeFileSync } from 'node:fs';
import { DEFAULT_CATEGORIES, type BulkDelta, type CategoryGlobs } from '../src/types.ts';
import { classifier, sectionOrder } from '../src/shared/classify.ts';
import { fileChange, fileStats, type Range } from '../src/server/sources/git.ts';
import { git } from '../src/server/exec.ts';

const cwd = new URL('..', import.meta.url).pathname;
const base = 'a76a1ce';  // "Sketch Prism's data model and README"
const head = git(cwd, ['rev-parse', 'HEAD']).trim();
const range: Range = { cwd, base, head };

const globs = DEFAULT_CATEGORIES['*'];
// A second set of rules, to show custom categories.
const customGlobs: CategoryGlobs = {
  spec: ['specs/**', 'README.md'],
  ui: ['src/ui/**'],
  test: ['test/**'],
  server: ['src/server/**', 'scripts/**'],
  shared: ['src/shared/**', 'src/types.ts'],
  other: ['bun.lock'],
};

const files = fileStats(range, globs)
  // Leave out the fixtures themselves: a fixture that contains itself never settles.
  .filter((f) => !f.path.startsWith('src/ui/fixtures/real/'))
  .map((stat) => fileChange(range, stat));

const custom = classifier(customGlobs);
const delta: BulkDelta = {
  id: 'github.com/diffplug/pridm:main',
  repo: 'github.com/diffplug/pridm',
  branch: 'main',
  base: { ref: base, sha: git(cwd, ['rev-parse', base]).trim() },
  title: 'pridm reviewing its own build',
  local: {
    path: '/Users/ntwigg/projects/pridm',
    headSha: head,
    uncommitted: { staged: 0, unstaged: 0, untracked: 0 },
    upstream: { ref: 'origin/main', ahead: 0, behind: 0 },
  },
  pr: null,
  surfaces: [],
  source: 'local',
};

const out = {
  delta,
  files,
  order: sectionOrder(globs),
  custom: {
    order: sectionOrder(customGlobs),
    categories: Object.fromEntries(files.map((f) => [f.path, custom(f.path)])),
  },
};
const path = new URL('../src/ui/fixtures/real/self.json', import.meta.url).pathname;
writeFileSync(path, JSON.stringify(out));
console.log(`${files.length} files, ${(JSON.stringify(out).length / 1024).toFixed(0)} KB → ${path}`);
for (const f of files) console.log(`  ${f.category.padEnd(6)} ${f.status.padEnd(8)} +${f.additions} −${f.deletions}  ${f.path}`);

// Runs git and other CLIs. node:child_process, because the server runs inside
// Vite, which runs on Node even when started with `bun run`.

import { execFileSync } from 'node:child_process';

export function run(command: string, args: string[], cwd: string): string {
  return execFileSync(command, args, { cwd, encoding: 'utf8', maxBuffer: 512 * 1024 * 1024 });
}

export function git(cwd: string, args: string[]): string {
  return run('git', args, cwd);
}

// A delta's changed files and their contents, from a local clone.
// See specs/architecture/discovery.md, "Where the diff comes from".
//
// With a `head`, compares two commits. Without one, compares `base` with the
// working tree, including uncommitted edits and files git doesn't track yet.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { CategoryGlobs, FileChange, FileStat, FileStatus } from '../../types.ts';
import { classifier } from '../../shared/classify.ts';
import { isMarkdown, languageOf } from '../../shared/language.ts';
import { mergeMarkdown } from '../../shared/mdmerge.ts';
import { wordCounts } from '../../shared/words.ts';
import { git } from '../exec.ts';

export interface Range {
  cwd: string;
  base: string;
  head?: string;  // undefined = the working tree
}

export function fileStats(range: Range, globs: CategoryGlobs): FileStat[] {
  const { cwd, base, head } = range;
  const revs = head ? [base, head] : [base];
  const classify = classifier(globs);

  const counts = parseNumstat(git(cwd, ['diff', '--numstat', '-z', '-M', ...revs]));
  const committed = head ? null : new Set(split(git(cwd, ['diff', '--name-only', '-z', '-M', base, 'HEAD'])));

  const stats: FileStat[] = parseNameStatus(git(cwd, ['diff', '--name-status', '-z', '-M', ...revs])).map((f) => {
    const c = counts.get(f.path);
    return {
      ...f,
      category: classify(f.status === 'deleted' ? (f.oldPath ?? f.path) : f.path),
      additions: c?.additions ?? 0,
      deletions: c?.deletions ?? 0,
      isBinary: c?.isBinary ?? false,
      committed: committed ? committed.has(f.path) : true,
    };
  });

  if (!head) {
    for (const path of split(git(cwd, ['ls-files', '--others', '--exclude-standard', '-z']))) {
      const text = readFileSync(join(cwd, path));
      const isBinary = text.includes(0);
      stats.push({
        path,
        status: 'added',
        category: classify(path),
        additions: isBinary ? 0 : text.toString('utf8').split('\n').length,
        deletions: 0,
        isBinary,
        committed: false,
      });
    }
  }
  // Markdown files are also counted in words. That means reading them, but
  // they're small, and the UI shows words for them instead of lines.
  for (const stat of stats) {
    if (!stat.isBinary && isMarkdown(stat.path)) {
      const { original, modified } = contents(range, stat);
      stat.words = wordCounts(original, modified);
    }
  }
  return stats.sort((a, b) => a.path.localeCompare(b.path));
}

function contents(range: Range, stat: FileStat): { original: string; modified: string } {
  const { cwd, base, head } = range;
  const show = (rev: string, path: string) => git(cwd, ['show', `${rev}:${path}`]);
  const original = stat.isBinary || stat.status === 'added' ? '' : show(base, stat.oldPath ?? stat.path);
  const modified =
    stat.isBinary || stat.status === 'deleted' ? '' : head ? show(head, stat.path) : readFileSync(join(cwd, stat.path), 'utf8');
  return { original, modified };
}

export function fileChange(range: Range, stat: FileStat): FileChange {
  const { original, modified } = contents(range, stat);
  if (isMarkdown(stat.path)) {
    return { ...stat, diff: { kind: 'markdown', original, modified, merged: mergeMarkdown(original, modified) } };
  }
  return { ...stat, diff: { kind: 'code', language: languageOf(stat.path), original, modified } };
}

// ─── Parsing git's -z output ─────────────────────────────────

function split(out: string): string[] {
  return out.split('\0').filter((s) => s !== '');
}

const STATUS: Record<string, FileStatus> = { A: 'added', C: 'added', M: 'modified', T: 'modified', D: 'deleted', R: 'renamed' };

// "M\0path\0", or "R100\0old\0new\0" for renames and copies.
function parseNameStatus(out: string): { path: string; oldPath?: string; status: FileStatus }[] {
  const t = split(out);
  const files = [];
  for (let i = 0; i < t.length; ) {
    const code = t[i]![0]!;
    if (code === 'R' || code === 'C') {
      files.push({ oldPath: code === 'R' ? t[i + 1] : undefined, path: t[i + 2]!, status: STATUS[code]! });
      i += 3;
    } else {
      files.push({ path: t[i + 1]!, status: STATUS[code] ?? 'modified' });
      i += 2;
    }
  }
  return files;
}

// "add\tdel\tpath\0", or "add\tdel\t\0old\0new\0" for renames. Binary files are "-\t-".
function parseNumstat(out: string): Map<string, { additions: number; deletions: number; isBinary: boolean }> {
  const t = out.split('\0');
  const counts = new Map();
  for (let i = 0; i < t.length; i++) {
    if (!t[i]) continue;
    const [add, del, path] = t[i]!.split('\t');
    let newPath = path;
    if (path === '') {
      newPath = t[i + 2];
      i += 2;
    }
    counts.set(newPath, { additions: Number(add) || 0, deletions: Number(del) || 0, isBinary: add === '-' });
  }
  return counts;
}

// Puts a path into a category, using one origin's globs. See specs/architecture/categories.md.

import picomatch from 'picomatch';
import { OTHER, type Category, type CategoryGlobs } from '../types.ts';

export type Classifier = (path: string) => Category;

// Categories are checked in the order they're written; the first match wins.
export function classifier(globs: CategoryGlobs): Classifier {
  const matchers = Object.entries(globs).map(([category, patterns]) => ({
    category,
    match: picomatch(patterns, { dot: true }),
  }));
  return (path) => matchers.find((m) => m.match(path))?.category ?? OTHER;
}

// The order of a delta's sections: the origin's categories as written, then OTHER.
export function sectionOrder(globs: CategoryGlobs): Category[] {
  return [...Object.keys(globs).filter((c) => c !== OTHER), OTHER];
}

// Monaco language ids by file extension. Markdown files get the rendered diff.

const BY_EXTENSION: Record<string, string> = {
  ts: 'typescript', tsx: 'typescript', mts: 'typescript', cts: 'typescript',
  js: 'javascript', jsx: 'javascript', mjs: 'javascript', cjs: 'javascript',
  json: 'json', jsonc: 'json', lock: 'json',
  css: 'css', scss: 'scss', less: 'less', html: 'html',
  md: 'markdown', mdx: 'markdown',
  yml: 'yaml', yaml: 'yaml', toml: 'ini', ini: 'ini',
  sh: 'shell', bash: 'shell', zsh: 'shell',
  py: 'python', go: 'go', java: 'java', kt: 'kotlin', kts: 'kotlin', gradle: 'java',
  rs: 'rust', rb: 'ruby', swift: 'swift', c: 'c', h: 'cpp', cpp: 'cpp', cs: 'csharp',
  sql: 'sql', xml: 'xml', svg: 'xml',
};

export function languageOf(path: string): string {
  const name = path.split('/').pop() ?? '';
  if (name === 'Dockerfile') return 'dockerfile';
  const ext = name.includes('.') ? name.split('.').pop()!.toLowerCase() : '';
  return BY_EXTENSION[ext] ?? 'plaintext';
}

export function isMarkdown(path: string): boolean {
  return languageOf(path) === 'markdown';
}

// Builds one markdown document that shows the changes between two versions:
// deleted text as ~~strikethrough~~ and inserted text as ==highlight==.
// MDXEditor renders both. See specs/architecture/diffs.md.
//
// 1. Split both versions into blocks (paragraph, heading, list item, ...).
// 2. Diff the lists of blocks.
// 3. Copy unchanged blocks, mark whole blocks that were added or deleted,
//    and mark only the changed words inside blocks that were edited.
//
// Code blocks, tables, HTML, and frontmatter can't hold inline marks. When one
// changes, it's shown under a label, old version then new.

import { fromMarkdown } from 'mdast-util-from-markdown';
import { gfmTable } from 'micromark-extension-gfm-table';
import { gfmTableFromMarkdown } from 'mdast-util-gfm-table';
import { diffArrays } from 'diff';
import type { RootContent } from 'mdast';

const DEL = '~~';
const INS = '==';

// Blocks whose text can hold inline marks. Everything else is atomic.
const TEXT_TYPES = new Set(['paragraph', 'heading', 'listItem', 'blockquote']);

const ATOMIC_NAMES: Record<string, string> = {
  code: 'code block',
  table: 'table',
  html: 'HTML',
  frontmatter: 'frontmatter',
  thematicBreak: 'divider',
  definition: 'link definition',
};

interface Block {
  type: string;     // mdast node type, or 'frontmatter'
  source: string;   // the block's markdown, exactly as written
  sep: string;      // the text between the previous block and this one
}

export function mergeMarkdown(original: string, modified: string): string {
  const a = splitBlocks(original);
  const b = splitBlocks(modified);
  const changes = diffArrays(a, b, {
    comparator: (x, y) => x.type === y.type && x.source === y.source,
  });

  const out: Piece[] = [];
  for (let i = 0; i < changes.length; i++) {
    const c = changes[i]!;
    if (!c.added && !c.removed) {
      for (const block of c.value) out.push(piece(block, safe(block)));
      continue;
    }
    // A run of removed blocks next to a run of added ones: pair them up.
    const next = changes[i + 1];
    let removed: Block[] = [];
    let added: Block[] = [];
    if (c.removed && next?.added) { removed = c.value; added = next.value; i++; }
    else if (c.added && next?.removed) { added = c.value; removed = next.value; i++; }
    else if (c.removed) removed = c.value;
    else added = c.value;

    out.push(...pairUp(removed, added));
  }
  return join(out);
}

// Lines up removed and added blocks of the same type, in order. Pairs that
// merge word by word are shown merged. Everything else between two merged
// pairs is shown as all the old blocks, then all the new ones, so a rewritten
// section reads as "before, after" instead of alternating.
function pairUp(removed: Block[], added: Block[]): Piece[] {
  const out: Piece[] = [];
  let dels: Block[] = [];
  let inss: Block[] = [];
  const flush = () => {
    out.push(...dels.map(deletedBlock), ...inss.map(insertedBlock));
    dels = [];
    inss = [];
  };

  let ia = 0;
  let ib = 0;
  for (const c of diffArrays(removed, added, { comparator: (x, y) => x.type === y.type })) {
    if (c.removed) { dels.push(...removed.slice(ia, ia + c.count)); ia += c.count; continue; }
    if (c.added) { inss.push(...added.slice(ib, ib + c.count)); ib += c.count; continue; }
    for (let k = 0; k < c.count; k++) {
      const old = removed[ia++]!;
      const neu = added[ib++]!;
      const merged = modifiedBlock(old, neu);
      if (merged) { flush(); out.push(merged); }
      else { dels.push(old); inss.push(neu); }
    }
  }
  flush();
  return out;
}

// ─── Splitting into blocks ───────────────────────────────────

const FRONTMATTER = /^---\n[\s\S]*?\n---[ \t]*(?:\n|$)/;

export function splitBlocks(markdown: string): Block[] {
  let text = markdown.replace(/\r\n?/g, '\n');
  const blocks: Block[] = [];

  const fm = FRONTMATTER.exec(text);
  if (fm) {
    blocks.push({ type: 'frontmatter', source: fm[0].trimEnd(), sep: '' });
    text = text.slice(fm[0].length);
  }

  const tree = fromMarkdown(text, {
    extensions: [gfmTable()],
    mdastExtensions: [gfmTableFromMarkdown()],
  });

  let prevEnd = 0;
  const add = (node: RootContent) => {
    const start = node.position!.start.offset!;
    const end = node.position!.end.offset!;
    blocks.push({ type: node.type, source: text.slice(start, end), sep: text.slice(prevEnd, start) });
    prevEnd = end;
  };
  for (const node of tree.children) {
    if (node.type === 'list') node.children.forEach(add);
    else add(node);
  }
  return blocks;
}

// ─── Emitting blocks ─────────────────────────────────────────

interface Piece {
  text: string;
  listItem: boolean;  // list items keep their own separators so lists stay tight
  sep: string;
}

function piece(block: Block, text: string): Piece {
  return { text, listItem: block.type === 'listItem', sep: block.sep };
}

function join(pieces: Piece[]): string {
  let out = '';
  pieces.forEach((p, i) => {
    if (i > 0) {
      const bothListItems = p.listItem && pieces[i - 1]!.listItem;
      out += bothListItems && p.sep.includes('\n') ? p.sep : bothListItems ? '\n' : '\n\n';
    }
    out += p.text;
  });
  return out + '\n';
}

// Atomic blocks MDXEditor can't render on its own are shown as code.
function safe(block: Block): string {
  if (block.type === 'frontmatter') {
    const inner = block.source.replace(/^---\n/, '').replace(/\n---$/, '');
    return '```yaml\n' + inner + '\n```';
  }
  if (block.type === 'html') return '```html\n' + block.source + '\n```';
  return block.source;
}

function isText(block: Block): boolean {
  return TEXT_TYPES.has(block.type);
}

function label(mark: string, word: string, block: Block): string {
  return `${mark}**${word} ${ATOMIC_NAMES[block.type] ?? block.type}**${mark}`;
}

function deletedBlock(block: Block): Piece {
  if (isText(block)) return piece(block, markBlock(block.source, DEL));
  return { text: label(DEL, 'Removed', block) + '\n\n' + safe(block), listItem: false, sep: block.sep };
}

function insertedBlock(block: Block): Piece {
  if (isText(block)) return piece(block, markBlock(block.source, INS));
  return { text: label(INS, 'Added', block) + '\n\n' + safe(block), listItem: false, sep: block.sep };
}

// Two versions of the same type of block, shown as one piece; or null when
// they're better shown as deleted + inserted.
function modifiedBlock(old: Block, neu: Block): Piece | null {
  if (!isText(neu)) {
    const text = [label(DEL, 'Old', neu), safe(old), label(INS, 'New', neu), safe(neu)].join('\n\n');
    return { text, listItem: false, sep: neu.sep };
  }
  const merged = mergeTextBlock(old.source, neu.source, neu.type);
  return merged === null ? null : piece(neu, merged);
}

// ─── Marking text ────────────────────────────────────────────

// Markdown that starts a line and must stay outside any mark:
// indentation, quote markers, list markers, task boxes, heading hashes.
const LINE_PREFIX = /^([ \t]*(?:>[ \t]?)*[ \t]*(?:(?:[-*+]|\d+[.)])[ \t]+)?(?:\[[ xX]\][ \t]+)?(?:#{1,6}[ \t]+)?)/;
const UNDERLINE = /^[ \t]*(?:=+|-+)[ \t]*$/;  // setext heading underline

// Marks every line of a block, keeping each line's markdown prefix outside the mark.
export function markBlock(source: string, mark: string): string {
  return source
    .split('\n')
    .map((line) => {
      if (UNDERLINE.test(line)) return line;
      const prefix = LINE_PREFIX.exec(line)![1]!;
      return prefix + markInline(line.slice(prefix.length), mark);
    })
    .join('\n');
}

// Marks text with no line prefixes, one line at a time. Whitespace stays
// outside the mark, because `~~ text~~` isn't valid strikethrough.
function markInline(text: string, mark: string): string {
  return text
    .split('\n')
    .map((line) => {
      const m = /^(\s*)(.*?)(\s*)$/.exec(line)!;
      return m[2] ? m[1] + mark + m[2] + mark + m[3] : line;
    })
    .join('\n');
}

// Above this share of changed words, an edited block reads better as
// "old block, new block" than as a patchwork of marks.
const MAX_CHANGED = 0.5;

// Diffs two versions of a text block word by word. Returns null when the block
// is better shown as deleted + inserted.
function mergeTextBlock(old: string, neu: string, type: string): string | null {
  const multiLine = old.includes('\n') || neu.includes('\n');
  if (multiLine) return type === 'paragraph' ? mergeWords(old, neu) : null;
  const po = LINE_PREFIX.exec(old)![1]!;
  const pn = LINE_PREFIX.exec(neu)![1]!;
  if (po !== pn) return null;
  const merged = mergeWords(old.slice(po.length), neu.slice(pn.length));
  return merged === null ? null : pn + merged;
}

interface Token {
  op: 'eq' | 'del' | 'ins';
  text: string;
}

const isSpace = (s: string) => /^\s+$/.test(s);

// Word-level merge. Tokens are whitespace-separated chunks, so every mark
// starts and ends next to whitespace, which keeps it valid markdown. A changed
// region grows into its neighbors until its markdown is balanced on both sides,
// so a mark never splits `**bold**`, `` `code` ``, or `[link](url)`.
export function mergeWords(old: string, neu: string): string | null {
  const tokenize = (s: string) => s.split(/(\s+)/).filter((t) => t !== '');
  const tokens: Token[] = [];
  for (const c of diffArrays(tokenize(old), tokenize(neu))) {
    const op = c.added ? 'ins' : c.removed ? 'del' : 'eq';
    for (const text of c.value) tokens.push({ op, text });
  }

  const words = tokens.filter((t) => !isSpace(t.text));
  const changed = words.filter((t) => t.op !== 'eq').length;
  const total = Math.max(1, words.filter((t) => t.op !== 'ins').length, words.filter((t) => t.op !== 'del').length);
  if (changed === 0) return neu;
  if (changed / 2 / total > MAX_CHANGED) return null;

  const side = (from: number, to: number, op: 'del' | 'ins') =>
    tokens.slice(from, to).filter((t) => t.op === 'eq' || t.op === op).map((t) => t.text).join('');

  const out: string[] = [];
  let floor = 0;  // the start of the region can't move back past here
  let i = 0;
  while (i < tokens.length) {
    if (tokens[i]!.op === 'eq') { out.push(tokens[i]!.text); i++; continue; }

    let start = i;
    let end = i;
    const grow = () => {
      while (end < tokens.length) {
        const t = tokens[end]!;
        const bridgesChanges = t.op === 'eq' && isSpace(t.text) && tokens[end + 1] && tokens[end + 1]!.op !== 'eq';
        if (t.op !== 'eq' || bridgesChanges) end++;
        else break;
      }
    };
    grow();

    for (;;) {
      const d = side(start, end, 'del');
      const n = side(start, end, 'ins');
      if (balanced(d) && balanced(n)) break;
      const canLeft = start > floor;
      const canRight = end < tokens.length;
      const goRight = direction(d, n, side(0, start, 'ins')) > 0 ? canRight : !canLeft;
      if (goRight && canRight) { end++; grow(); }
      else if (canLeft) { start--; out.pop(); }
      else return null;
    }

    const del = markInline(side(start, end, 'del'), DEL);
    const ins = markInline(side(start, end, 'ins'), INS);
    const gap = del.trim() && ins.trim() && !/\s$/.test(del) && !/^\s/.test(ins) ? ' ' : '';
    out.push(del + gap + ins);
    i = end;
    floor = end;
  }
  return out.join('');
}

const count = (s: string, re: RegExp) => (s.match(re) ?? []).length;

// > 0: something is opened but not closed, so grow right.
// < 0: something is closed but not opened, so grow left.
function imbalance(s: string): number {
  const brackets = count(s, /\[/g) - count(s, /\]/g);
  const parens = count(s, /\(/g) - count(s, /\)/g);
  return brackets || parens;
}

// Which way an unbalanced region should grow: > 0 right, < 0 left.
// For brackets that's clear from which side is missing. For ` and *, which
// open and close with the same character, it depends on what's before the
// region: an odd number before it means the region closes a span.
function direction(del: string, ins: string, before: string): number {
  const brackets = imbalance(del) || imbalance(ins);
  if (brackets) return brackets;
  for (const re of [/`+/g, /\*+/g]) {
    if (count(del, re) % 2 || count(ins, re) % 2) return count(before, re) % 2 ? -1 : 1;
  }
  return 1;
}

function balanced(s: string): boolean {
  return (
    imbalance(s) === 0 &&
    count(s, /\*+/g) % 2 === 0 &&  // runs of *, so `**bold**` counts as two
    count(s, /`+/g) % 2 === 0
  );
}

// Groups a delta's files into categories, for the UI. Pure, so the server and
// Storybook fixtures build the same shapes.

import type { BulkDelta, Category, CategoryDiff, CategoryStat, DeltaOverview, FileChange, FileStat } from '../types.ts';

// In section order. Categories with no files are left out.
export function categoryStats(files: FileStat[], order: Category[]): CategoryStat[] {
  return order
    .map((category) => {
      const inCategory = files.filter((f) => f.category === category);
      const allMarkdown = inCategory.length > 0 && inCategory.every((f) => f.words);
      return {
        category,
        fileCount: inCategory.length,
        additions: sum(inCategory, 'additions'),
        deletions: sum(inCategory, 'deletions'),
        ...(allMarkdown && {
          words: {
            added: inCategory.reduce((n, f) => n + f.words!.added, 0),
            removed: inCategory.reduce((n, f) => n + f.words!.removed, 0),
          },
        }),
      };
    })
    .filter((s) => s.fileCount > 0);
}

export function buildOverview(delta: BulkDelta, files: FileStat[], order: Category[]): DeltaOverview {
  return {
    delta,
    categories: categoryStats(files, order).map((stat) => ({
      ...stat,
      files: files.filter((f) => f.category === stat.category).map(toStat),
    })),
  };
}

export function categoryDiff(deltaId: string, category: Category, files: FileChange[]): CategoryDiff {
  return { deltaId, category, files: files.filter((f) => f.category === category) };
}

// Strip the diff from a FileChange, leaving the FileStat.
export function toStat(f: FileStat): FileStat {
  const { path, oldPath, status, category, additions, deletions, isBinary, committed, words } = f;
  return { path, oldPath, status, category, additions, deletions, isBinary, committed, words };
}

function sum(files: FileStat[], key: 'additions' | 'deletions'): number {
  return files.reduce((n, f) => n + f[key], 0);
}

// Words added and removed between two versions of a markdown file. Words are
// whitespace-separated, the same chunks the merged markdown marks, so the
// counts match what's highlighted. Markdown syntax on its own (`##`, `-`, `|`,
// `1.`, code fences) doesn't count as a word.

import { diffArrays } from 'diff';

const SYNTAX = /^(?:[#>*+|=~:-]+|\d+[.)]|`{3,}.*|\[[ xX]?\])$/;

export function words(text: string): string[] {
  return text.split(/\s+/).filter((w) => w !== '' && !SYNTAX.test(w));
}

export function wordCounts(original: string, modified: string): { added: number; removed: number } {
  let added = 0;
  let removed = 0;
  for (const c of diffArrays(words(original), words(modified))) {
    if (c.added) added += c.count;
    if (c.removed) removed += c.count;
  }
  return { added, removed };
}

