function bigFile(changed: boolean): string {
  const lines: string[] = [];
  for (let i = 0; i < 400; i++) {
    const value = changed && (i === 40 || i === 41 || i === 300) ? `${i} * 2` : `${i}`;
    lines.push(`export const value${i} = ${value};`);
