.pridm-status {
  font-family: var(--fontStack-sansSerif);
  font-size: 11px;
  padding: 0 6px;
  border-radius: 999px;
  border: 1px solid var(--borderColor-default);
  color: var(--fgColor-muted);
}

.pridm-additions {
  color: var(--fgColor-success);
}

.pridm-deletions {
  color: var(--fgColor-danger);
}

.pridm-toggle {
  display: inline-flex;
  border: 1px solid var(--borderColor-default);
  border-radius: 6px;
  overflow: hidden;
}

.pridm-toggle button {
  font: inherit;
  font-family: var(--fontStack-sansSerif);
  font-size: 12px;
  padding: 2px 8px;
  border: 0;
  background: var(--bgColor-default);
  color: var(--fgColor-default);
  cursor: pointer;
}

.pridm-toggle button[aria-pressed='true'] {
  background: var(--bgColor-accent-emphasis);
  color: var(--fgColor-onEmphasis);
}

.pridm-file-note {
  padding: 16px;
  color: var(--fgColor-muted);
  font-style: italic;
}

/* ─── Code diff ───────────────────────────────────────────── */

/* A change shown inline on one line: a light gutter, to match its light line.
   See markInlineChanges in CodeDiffView.tsx. */
.margin-view-overlays > div:has(> .pridm-inline-change) > .gutter-insert {
  background: var(--diffBlob-additionLine-bgColor);
}

.margin-view-overlays > div:has(> .pridm-inline-change) > .gutter-delete {
  background: var(--diffBlob-deletionLine-bgColor);
}

/* ─── Markdown diff ───────────────────────────────────────── */

.pridm-md {
  padding: 4px 16px;
  color: var(--fgColor-default);
  font-family: var(--fontStack-sansSerif);
}

/* ==inserted== and ~~deleted~~, including inline code inside them.
   The classes come from MarkdownDiffView's Lexical theme. */
.pridm-md mark {
  background: none;
  color: inherit;
}

.pridm-md .pridm-ins {
  background: var(--diffBlob-additionWord-bgColor);
  color: var(--diffBlob-additionWord-fgColor);
  border-radius: 2px;
}

.pridm-md .pridm-del {
  background: var(--diffBlob-deletionWord-bgColor);
  color: var(--diffBlob-deletionWord-fgColor);
  text-decoration: line-through;
  border-radius: 2px;
}

.pridm-md pre {
  background: var(--bgColor-muted);
  border-radius: 6px;
  padding: 12px;
  font-family: var(--fontStack-monospace);
  font-size: 12px;
  overflow-x: auto;
}

.pridm-md table {
  border-collapse: collapse;
}

.pridm-md th,
.pridm-md td {
  border: 1px solid var(--borderColor-default);
  padding: 4px 10px;
}

.pridm-md a {
  color: var(--fgColor-accent);
}

/* ─── Delta view ──────────────────────────────────────────── */

.pridm-muted {
  color: var(--fgColor-muted);
}

.pridm-attention {
  color: var(--fgColor-attention);
}

.pridm-delta {
  max-width: 1280px;
}

.pridm-delta-header h2 {
  margin: 0 0 4px;
  font-size: 20px;
  font-weight: 600;
}

.pridm-delta-total {
  font-size: 14px;
  font-weight: 400;
  font-family: var(--fontStack-monospace);
}

.pridm-facts {
  color: var(--fgColor-muted);
  margin-bottom: 16px;
}

.pridm-facts code {
  font-family: var(--fontStack-monospace);
  font-size: 12px;
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--bgColor-accent-muted);
  color: var(--fgColor-accent);
}

.pridm-facts a {
  color: var(--fgColor-accent);
}

.pridm-section {
  margin-bottom: 4px;
}

.pridm-section > summary {
  cursor: pointer;
  list-style: none;
  user-select: none;
  position: sticky;
  top: 0;
  z-index: 6;
  background: var(--bgColor-default);
}

.pridm-section > summary::-webkit-details-marker {
  display: none;
}

.pridm-section > summary:hover .pridm-section-rule {
  border-color: var(--borderColor-emphasis);
}

.pridm-section-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  height: var(--pridm-section-header-height);
  box-sizing: border-box;
  /* lines the +/− up with the file rows' +/− (their padding + border) */
  padding-right: 13px;
}

/* the line from the name to the counts */
.pridm-section-rule {
  flex: 1;
  border-top: 1px solid var(--borderColor-default);
}

.pridm-section-summary::before {
  content: '▸';
  color: var(--fgColor-muted);
  width: 10px;
}

.pridm-section[open] .pridm-section-summary::before {
  content: '▾';
}

.pridm-section-name {
  font-size: 16px;
  font-weight: 600;
}

.pridm-plusminus,
.pridm-counts {
  font-variant-numeric: tabular-nums;
  font-family: var(--fontStack-monospace);
  font-size: 12px;
}

.pridm-section-body {
  padding: 4px 0 12px;
}


.pridm-category-name {
  font-family: var(--fontStack-sansSerif);
  font-weight: 600;
}

import { useEffect, useState } from 'react';
import type { Monaco } from '@monaco-editor/react';

// Light or dark comes from <html data-color-mode="light | dark | auto">,
// the same attribute Primer's CSS reads.
function readIsDark(): boolean {
  const mode = document.documentElement.getAttribute('data-color-mode');
  if (mode === 'dark') return true;
  if (mode === 'light') return false;
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
}

export function useIsDark(): boolean {
  const [dark, setDark] = useState(readIsDark);
  useEffect(() => {
    const update = () => setDark(readIsDark());
    const observer = new MutationObserver(update);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-color-mode'] });
    const media = window.matchMedia('(prefers-color-scheme: dark)');
    media.addEventListener('change', update);
    return () => {
      observer.disconnect();
      media.removeEventListener('change', update);
    };
  }, []);
  return dark;
}

// Monaco can't read CSS variables, so its theme is built from Primer's
// current values. Call this after the color mode is applied.
function cssVar(name: string): string | undefined {
  const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return value.startsWith('#') ? value : undefined;
}

export function monacoThemeName(dark: boolean): string {
  return dark ? 'pridm-dark' : 'pridm-light';
}

export function defineMonacoTheme(monaco: Monaco, dark: boolean): string {
  const colors: Record<string, string | undefined> = {
    'editor.background': cssVar('--bgColor-default'),
    'editor.foreground': cssVar('--fgColor-default'),
    'editorLineNumber.foreground': cssVar('--fgColor-muted'),
    'editorGutter.background': cssVar('--bgColor-default'),
    'diffEditor.insertedTextBackground': cssVar('--diffBlob-additionWord-bgColor'),
    'diffEditor.removedTextBackground': cssVar('--diffBlob-deletionWord-bgColor'),
    'diffEditor.insertedLineBackground': cssVar('--diffBlob-additionLine-bgColor'),
    'diffEditor.removedLineBackground': cssVar('--diffBlob-deletionLine-bgColor'),
    'diffEditorGutter.insertedLineBackground': cssVar('--diffBlob-additionNum-bgColor'),
    'diffEditorGutter.removedLineBackground': cssVar('--diffBlob-deletionNum-bgColor'),
    'diffEditor.unchangedRegionBackground': cssVar('--bgColor-muted'),
  };
  const name = monacoThemeName(dark);
  monaco.editor.defineTheme(name, {
    base: dark ? 'vs-dark' : 'vs',
    inherit: true,
    rules: [],
    colors: Object.fromEntries(Object.entries(colors).filter(([, v]) => v)) as Record<string, string>,
  });
  return name;
}

import { describe, expect, test } from 'bun:test';
import { DEFAULT_CATEGORIES, OTHER, type FileStat } from '../src/types.ts';
import { classifier, sectionOrder } from '../src/shared/classify.ts';
import { categoryStats } from '../src/shared/overview.ts';

describe('classifier', () => {
  const classify = classifier(DEFAULT_CATEGORIES['*']);

  test('default rules', () => {
    expect(classify('specs/plan.md')).toBe('spec');
    expect(classify('README.md')).toBe('spec');
    expect(classify('test/mdmerge.test.ts')).toBe('test');
    expect(classify('src/foo.spec.ts')).toBe('test');
    expect(classify('src/shared/mdmerge.ts')).toBe('prod');
    expect(classify('bun.lock')).toBe(OTHER);
    expect(classify('.github/workflows/ci.yml')).toBe(OTHER);
  });

  test('the first matching category wins', () => {
    expect(classify('test/README.md')).toBe('spec');
    const testFirst = classifier({ test: ['test/**'], spec: ['**/*.md'] });
    expect(testFirst('test/README.md')).toBe('test');
  });

  test('custom categories, and listing other to claim files early', () => {
    const c = classifier({ migrations: ['db/migrations/**'], other: ['**/generated/**'], prod: ['**'] });
    expect(c('db/migrations/001.sql')).toBe('migrations');
    expect(c('src/generated/api.ts')).toBe(OTHER);
    expect(c('src/api.ts')).toBe('prod');
  });

  test('dotfiles match', () => {
    expect(classifier({ ci: ['.github/**'] })('.github/workflows/ci.yml')).toBe('ci');
  });
});

describe('sectionOrder', () => {
  test('categories as written, then other last', () => {
    expect(sectionOrder({ other: ['x'], spec: ['y'], test: ['z'] })).toEqual(['spec', 'test', OTHER]);
  });
});

describe('categoryStats', () => {
  const file = (path: string, category: string, additions: number, deletions: number): FileStat => ({
    path, category, additions, deletions, status: 'modified', isBinary: false, committed: true,
  });

  test('sums per category, in order, leaving out empty ones', () => {
    const stats = categoryStats(
      [file('a.md', 'spec', 3, 1), file('b.md', 'spec', 2, 0), file('a.ts', 'prod', 10, 5)],
      ['spec', 'test', 'prod', OTHER],
    );
    expect(stats).toEqual([
      { category: 'spec', fileCount: 2, additions: 5, deletions: 1 },
      { category: 'prod', fileCount: 1, additions: 10, deletions: 5 },
    ]);
  });
});

import { describe, expect, test } from 'bun:test';
import { mergeMarkdown } from '../src/shared/mdmerge.ts';

const merge = (a: string, b: string) => mergeMarkdown(a, b).trimEnd();

describe('mergeMarkdown', () => {
  test('identical documents are unchanged', () => {
    const doc = '# Title\n\nSome text.\n\n- a\n- b';
    expect(merge(doc, doc)).toBe(doc);
  });

  test('a word changed in a paragraph', () => {
    expect(merge('The quick brown fox.', 'The quick red fox.')).toBe('The quick ~~brown~~ ==red== fox.');
  });

  test('a heading renamed keeps its hashes outside the marks', () => {
    expect(merge('## Old title', '## New title')).toBe('## ~~Old~~ ==New== title');
  });

  test('a heading whose level changed is shown as deleted + inserted', () => {
    expect(merge('## Title', '### Title')).toBe('## ~~Title~~\n\n### ==Title==');
  });

  test('a list item added keeps the list tight', () => {
    expect(merge('- a\n- b', '- a\n- b\n- c')).toBe('- a\n- b\n- ==c==');
  });

  test('a list item edited', () => {
    expect(merge('- buy milk\n- buy eggs', '- buy milk\n- buy bread')).toBe('- buy milk\n- buy ~~eggs~~ ==bread==');
  });

  test('a task list item keeps its checkbox outside the marks', () => {
    expect(merge('- [ ] a', '- [ ] a\n- [x] done')).toBe('- [ ] a\n- [x] ==done==');
  });

  test('a block deleted', () => {
    expect(merge('Para one.\n\nPara two.', 'Para one.')).toBe('Para one.\n\n~~Para two.~~');
  });

  test('a block inserted between others', () => {
    expect(merge('One.\n\nThree.', 'One.\n\nTwo.\n\nThree.')).toBe('One.\n\n==Two.==\n\nThree.');
  });

  test('a code block changed is shown old then new', () => {
    const a = '```ts\nconst x = 1;\n```';
    const b = '```ts\nconst x = 2;\n```';
    expect(merge(a, b)).toBe(`~~**Old code block**~~\n\n${a}\n\n==**New code block**==\n\n${b}`);
  });

  test('a table changed is shown old then new', () => {
    const a = '| a | b |\n| - | - |\n| 1 | 2 |';
    const b = '| a | b |\n| - | - |\n| 1 | 3 |';
    expect(merge(a, b)).toBe(`~~**Old table**~~\n\n${a}\n\n==**New table**==\n\n${b}`);
  });

  test('a code block added gets a label', () => {
    expect(merge('Text.', 'Text.\n\n```\nnew\n```')).toBe('Text.\n\n==**Added code block**==\n\n```\nnew\n```');
  });

  test('a mark never splits bold text', () => {
    expect(merge('This is **very important** stuff.', 'This is **really important** stuff.')).toBe(
      'This is ~~**very important**~~ ==**really important**== stuff.',
    );
  });

  test('a mark never splits a link', () => {
    expect(merge('See [the docs](a.md) now.', 'See [the docs](b.md) now.')).toBe(
      'See ~~[the docs](a.md)~~ ==[the docs](b.md)== now.',
    );
  });

  test('a mark never splits inline code', () => {
    expect(merge('Run `npm run dev` first.', 'Run `bun run dev` first.')).toBe(
      'Run ~~`npm run dev`~~ ==`bun run dev`== first.',
    );
  });

  test('punctuation changes take the whole word, so the marks stay valid', () => {
    expect(merge('It is done.', 'It is done!')).toBe('It is ~~done.~~ ==done!==');
  });

  test('a mostly rewritten paragraph is shown as deleted + inserted', () => {
    expect(merge('The old way of doing things.', 'A completely different sentence here.')).toBe(
      '~~The old way of doing things.~~\n\n==A completely different sentence here.==',
    );
  });

  test('a change in a multi-line paragraph marks each line separately', () => {
    expect(merge('one two\nthree four', 'one 2\n3 four')).toBe('one ~~two~~\n~~three~~ ==2==\n==3== four');
  });

  test('a rewritten section shows all the old blocks, then all the new ones', () => {
    const a = 'Intro.\n\nThe old explanation of colors.\n\n- strip on the left\n- bar on each row';
    const b = 'Intro.\n\nNo colors at all, names only.\n\n- header shows counts';
    expect(merge(a, b)).toBe(
      'Intro.\n\n~~The old explanation of colors.~~\n\n- ~~strip on the left~~\n- ~~bar on each row~~\n\n' +
        '==No colors at all, names only.==\n\n- ==header shows counts==',
    );
  });

  test('frontmatter is shown as a yaml code block', () => {
    expect(merge('---\ntitle: a\n---\n\nText.', '---\ntitle: a\n---\n\nText.')).toBe('```yaml\ntitle: a\n```\n\nText.');
  });

  test('raw HTML is shown as an html code block', () => {
    expect(merge('<div>hi</div>', '<div>hi</div>')).toBe('```html\n<div>hi</div>\n```');
  });
});

import { describe, expect, test } from 'bun:test';
import { wordCounts } from '../src/shared/words.ts';
import { categoryStats } from '../src/shared/overview.ts';
import type { FileStat } from '../src/types.ts';

describe('wordCounts', () => {
  test('a word changed', () => {
    expect(wordCounts('The quick brown fox.', 'The quick red fox.')).toEqual({ added: 1, removed: 1 });
  });

  test('markdown syntax is not a word', () => {
    expect(wordCounts('', '## Title\n\n- one\n- two\n\n| a | b |\n| - | - |')).toEqual({ added: 5, removed: 0 });
  });

  test('a new file counts every word', () => {
    expect(wordCounts('', 'four words right here')).toEqual({ added: 4, removed: 0 });
  });
});

describe('categoryStats words', () => {
  const file = (path: string, words?: { added: number; removed: number }): FileStat => ({
    path, category: 'spec', additions: 1, deletions: 1, status: 'modified', isBinary: false, committed: true, words,
  });

  test('summed when every file is markdown', () => {
    const [s] = categoryStats([file('a.md', { added: 3, removed: 1 }), file('b.md', { added: 2, removed: 2 })], ['spec']);
    expect(s!.words).toEqual({ added: 5, removed: 3 });
  });

  test('left out when any file is not markdown, so the units never mix', () => {
    const [s] = categoryStats([file('a.md', { added: 3, removed: 1 }), file('a.ts')], ['spec']);
    expect(s!.words).toBeUndefined();
  });
});

